import{_ as d,a0 as r,w as a,s as m,ao as i,I as o,x as s,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"systemd-nspawn 快速指南 | LCTT x X-CMD","titleTemplate":false,"description":"systemd-nspawn 快速指南 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"systemd-nspawn 快速指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"systemd-nspawn 快速指南 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/Quick systemd-nspawn guide","title":"systemd-nspawn 快速指南","tag":"201501","desc":""},"relativePath":"201501/Quick systemd-nspawn guide.md","filePath":"[post].md"}'),y={name:"201501/Quick systemd-nspawn guide.md"};function l(u,t,c,w,h,f){const e=r("Link");return a(),m("div",null,[t[13]||(t[13]=i(`<h1 id="systemd-nspawn-快速指南" tabindex="-1">systemd-nspawn 快速指南 <a class="header-anchor" href="#systemd-nspawn-快速指南" aria-label="Permalink to “systemd-nspawn 快速指南”">​</a></h1><p>我目前已從 chroot（譯者注：chroot可以構建類似沙盒的環境，建議各位同學先了解chroot） 遷移到 systemd-nspawn，同時我寫了一篇快速指南。簡單的説，我強烈建議正在使用 systemd 的用户從 chroot 轉為 systemd-nspawn，因為只要你的內核配置正確的話，它幾乎沒有什麼缺點。</p><p>想必在各大發行版中的用户對 chroot 都不陌生，而且我猜想 Gentoo 用户要時不時的使用它。</p><p>###chroot 面臨的挑戰</p><p>大多數交互環境下，僅運行chroot還不夠。通常還要掛載 /proc， /sys，另外為了確保不會出現類似“丟失 ptys”之類的錯誤，我們還得 bind（譯者注：bind 是 mount 的一個選項） 掛載 /dev。如果你使用 tmpfs，你可能想要以 tmpfs 類型掛載新的 tmp、 var/tmp。接下來你可能還想將其他的掛載點 bind 到 chroot 中。這些都不是特別難，但是一般情況下要寫一個腳本來管理它。</p><p>現在我按照日常計劃執行備份操作，當然有一些不必備份的數據如 tmp 目錄，或任何 bind 掛載的內容。當我配置了一個新的 chroot 後就意味着我要更新我的備份配置了，但我經常忘記這點，因為大多數時間裏 chroot 掛載點並沒有運行。當這些掛載點仍然存在的情況下執行備份的話，那麼備份中會多出很多不需要的內容。</p><p>當 bind 掛載點包含其他掛載點時（比如掛載時使用 -rbind 選項），這種情況下 systemd 的默認處理方式略有不同。在 bind 掛載中卸載一些東西時，systemd 會將處於 bind 另一邊的目錄也卸載掉。想像一下，如果我卸載了 chroot 中以 bind 掛載 /dev 的某個目錄後，發現主機上的 /dev/pts 與 /dev/shm 也不見了，我肯定會很吃驚。不過好像有其他方法可以避免，但是這不是我們此次討論的重點。</p><h3 id="systemd-nspawn-優點" tabindex="-1">Systemd-nspawn 優點 <a class="header-anchor" href="#systemd-nspawn-優點" aria-label="Permalink to “Systemd-nspawn 優點”">​</a></h3><p>Systemd-nspawn 用於啓動一個容器，並且它的最簡模式就可以像 chroot 那樣運行。默認情況下，它自動配置容器所需的開銷如 /dev, /tmp 等等。通過配合一些選項它也可配置其他的 bind 掛載點。當容器退出後，所有的掛載點都會被清除。</p><p>容器運行時，從外部看上去沒什麼變化。事實上，可以從同一個 chroot 產生5個不同的 systemd-nspawn 容器實例，並且除了文件系統（不包括 /dev, /tmp等，只有 /usr,/etc 的改變會傳遞）外它們之間沒有任何聯繫。你的備份將會忽略 bind 掛載點、tmpfs 及任何掛載在容器中的內容。</p><p>它同時具有其它優秀容器的優點，比如 containment - 可以殺死容器內的所有活動但不影響外部，等等。它的安全性並不是無懈可擊的-它的作用僅僅是防止意外的錯誤。</p><p>如果你使用的是兼容的 sysvinit（它包含了 systemd，openrc），你可以啓動容器。這意味着，你可以在容器中使用 fstab 添加掛載點，運行守護進程等。只需要一個 chroot 的開銷，幾乎就可以獲得虛擬化的所有好處（不需要構建內核等）。在一個看起來像 chroot 的容器中運行systemctl poweroff 看起來很奇怪，但這條命令能夠起作用。</p><p>注意，如果不做額外配置的話那麼容器就會共享主機的網絡，所以主機上的容器不要運行 sshd。運行一個分離的網絡 namespace 不是太難，為了新的實例可以使用DHCP，分離之後記得綁定接口。</p><p>###操作步驟</p><p>讓它工作起來是此次討論中最簡短的部分了。</p><p>首先系統內核要支持 namespaces 與 devpts：</p><pre><code>CONFIG_UTS_NS=y
CONFIG_IPC_NS=y
CONFIG_USER_NS=y
CONFIG_PID_NS=y
CONFIG_NET_NS=y
CONFIG_DEVPTS_MULTIPLE_INSTANCES=y
</code></pre><p>像 chroot 那樣啓動 namespace 是非常簡單的：</p><pre><code>systemd-nspawn -D .
</code></pre><p>也可以像 chroot 那樣退出。在內部可以運行 mount 並且可以看到默認它已將 /dev 與 /tmp 準備好了。 ”.“就是 chroot 的路徑，也就是當前路徑。在它內部運行的是 bash。</p><p>如果要添加一些 bind 掛載點也非常簡便：</p><pre><code>systemd-nspawn -D . --bind /usr/portage
</code></pre><p>現在，容器中的 /usr/portage 就與主機的對應目錄綁定起來了，我們無需 sync /etc。如果想要綁定到指定的路徑，只要在原路徑後添加 ”:dest“，相當於 chroot 的 root（--bind foo 與 --bind foo:foo是一樣的）。</p><p>如果容器具有 init 功能並且可以在內部運行，可以通過添加 -b 選項啓動它：</p><pre><code>systemd-nspawn -D . --bind /usr/portage -b
</code></pre><p>可以觀察到 init 的運作。關閉容器會自動退出。</p><p>如果容器內運行了 systemd ，你可以使用 -h 選項將它的日誌重定向到主機的systemd日誌：</p><pre><code>systemd-nspawn -D . --bind /usr/portage -j -b
</code></pre><p>使用 nspawn 註冊容器以便它能夠在 machinectl 中顯示。如此可以方便的在主機上對它進行操作，如啓動新的 getty， ssh 連接，關機等。</p><p>如果你正在使用 systemd 那麼甩開 chroot 擁抱 nspawn 吧。</p><hr>`,31)),o("p",null,[t[1]||(t[1]=s("via: ",-1)),n(e,{href:"http://rich0gentoo.wordpress.com/2014/07/14/quick-systemd-nspawn-guide/"},{default:p(()=>[...t[0]||(t[0]=[s("http://rich0gentoo.wordpress.com/2014/07/14/quick-systemd-nspawn-guide/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=s("作者：",-1)),n(e,{href:"http://rich0gentoo.wordpress.com/"},{default:p(()=>[...t[2]||(t[2]=[s("rich0",-1)])]),_:1}),t[6]||(t[6]=s(" 譯者：",-1)),n(e,{href:"https://github.com/SPccman"},{default:p(()=>[...t[3]||(t[3]=[s("SPccman",-1)])]),_:1}),t[7]||(t[7]=s(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[4]||(t[4]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[8]||(t[8]=[s("LCTT",-1)])]),_:1}),t[11]||(t[11]=s(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:p(()=>[...t[9]||(t[9]=[s("Linux中國",-1)])]),_:1}),t[12]||(t[12]=s(" 榮譽推出",-1))])])}const g=d(y,[["render",l]]);export{C as __pageData,g as default};
